    if (!Number.isSafeInteger(closedAtMs) || ageSeconds < -30 || ageSeconds > c.operations.maxLedgerAgeSeconds)
      return {state:'STALE_LEDGER',ready:false,checks,ledger:observedLedger,health:observedHealth};
