// MIT. Complete exact-source handover and separate-project restoration.
import {gzipSync,gunzipSync} from 'node:zlib';
import {readFileSync,readdirSync,statSync,existsSync} from 'node:fs';
import {resolve,relative,dirname,join,sep,extname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {need,plain,sha,uuid,now,jsonBytes,base64,LIMITS,clone} from '../common.mjs';

const SCHEMA='stellar-forge.coingecko-handover.v1';
const featureRoot=fileURLToPath(new URL('../',import.meta.url));
const repositoryRoot=resolve(featureRoot,'../../../..');
const within=path=>{const rel=relative(repositoryRoot,path);return rel&&!rel.startsWith('..'+sep)&&rel!=='..'&&!rel.startsWith(sep)};
function runtimeSources(){
  const queue=[],seen=new Set(),files=[];
  function add(path){if(within(path)&&existsSync(path)&&statSync(path).isFile()&&!seen.has(path)){seen.add(path);queue.push(path)}}
  // Retain published product source, never an operator-selected state subtree.
  const productFiles=["common.mjs","exact-json.mjs","contracts.mjs","market.mjs","provider.mjs","cli.mjs","workspace/store.mjs","workspace/capture.mjs","workspace/model.mjs","workspace/jobs.mjs","workspace/native-worker.mjs","workspace/recovery.mjs","workspace/server.mjs","workspace/managed.mjs","README.md","collection.example.json","runtime-dependencies.json","workspace/public/index.html","workspace/public/app.mjs","workspace/public/style.css"];
  productFiles.push(...["workspace/acceptance/collect-provider-sources.mjs","workspace/acceptance/sources.example.json","workspace/acceptance/launch-native.py","workspace/acceptance/native-environment.mjs","workspace/acceptance/native.example.json","workspace/acceptance/README.md","workspace/acceptance/run-browser.mjs"]);
  for(const name of productFiles)add(join(featureRoot,name));
  // The original SF30 portal loads its assets from a runtime filename table.
  // Preserve every original asset explicitly; module-import traversal cannot
  // discover the table's concatenated paths.
  for(const name of ['index.html','browser.mjs','request.mjs','style.css']){
    const path=resolve(featureRoot,'../../sf30-seller-sdk/developer',name);
    need(existsSync(path)&&statSync(path).isFile(),'ORIGINAL_RUNTIME_SOURCE_MISSING',
      'The original SF30 developer portal asset is missing: '+name);
    add(path);
  }
  // SF88's original Python ledger initializer resolves this directory at runtime.
  add(resolve(featureRoot,'../../sf36-spend-governor/governor.py'));
  // Preserve the original provider-operated in-process facilitator option as well.
  add(resolve(featureRoot,'../../native-facilitator/runtime.mjs'));
  add(resolve(featureRoot,'../../distribution/distribution.json'));
  add(resolve(featureRoot,'../../sf61-openapi-seller-import/package.json'));
  add(resolve(featureRoot,'../../../../stellar-forge/payment-auto-catalog/package.json'));
  for(const name of ['LICENSE','LICENSE.md','package.json'])add(join(repositoryRoot,name));
  let bytesTotal=0;
  while(queue.length){
    const path=queue.shift(),bytes=readFileSync(path);bytesTotal+=bytes.length;
    need(bytesTotal<=32*1024*1024&&files.length<3000,'SOURCE_PACKAGE_TOO_LARGE');
    files.push({path:relative(repositoryRoot,path).split(sep).join('/'),sha256:sha(bytes),bytes:bytes.length,contentBase64:bytes.toString('base64')});
    if(extname(path)==='.py'){
      const python=bytes.toString('utf8');
      for(const match of python.matchAll(/^(?:from\s+([A-Za-z_][\w.]*)\s+import|import\s+([A-Za-z_][\w.]*))/gm)){
        add(resolve(dirname(path),(match[1]??match[2]).replaceAll('.','/')+'.py'));
      }
    }
    if(!['.mjs','.js','.cjs'].includes(extname(path)))continue;
    const text=bytes.toString('utf8');
    const patterns=[/(?:from\s*|import\s*\(|new\s+URL\s*\()\s*['"](\.[^'"]+)['"]/g,/import\s*['"](\.[^'"]+)['"]/g];
    for(const pattern of patterns)for(const match of text.matchAll(pattern)){
      const candidate=resolve(dirname(path),match[1]);
      if(extname(candidate))add(candidate);
    }
  }
  files.sort((a,b)=>a.path.localeCompare(b.path));
  return{schema:'stellar-forge.coingecko-runtime-source.v1',node:'24 or later',entry:relative(repositoryRoot,join(featureRoot,'cli.mjs')).split(sep).join('/'),
    dependencyMode:'Original Starforge source closure. Install the declared original x402 packages for native payment. Existing operator keys and live ledgers remain external.',
    files};
}
export function createProjectArchive(store,projectId,selection={}){
  const payload=store.exportProject(projectId),runtime=runtimeSources();
  const archive={schema:SCHEMA,createdAt:now(),selection,payload,runtime,
    payloadSha256:sha(jsonBytes(payload)),runtimeSha256:sha(jsonBytes(runtime)),
    contents:'Private original market sources, project history, original native summaries and runnable source; no signer keys or live payment ledgers.'};
  const raw=jsonBytes(archive);need(raw.length<=LIMITS.restoreExpandedBytes,'HANDOVER_TOO_LARGE','Complete handover exceeds the expanded restore limit');
  const bytes=gzipSync(raw,{level:6,mtime:0});need(bytes.length<=LIMITS.restoreBytes,'HANDOVER_TOO_LARGE','Compressed handover exceeds the restore limit');return bytes;
}
export function readProjectArchive(bytes){
  need(bytes instanceof Uint8Array&&bytes.length<=LIMITS.restoreBytes,'INVALID_HANDOVER');
  let archive;try{archive=JSON.parse(gunzipSync(bytes,{maxOutputLength:LIMITS.restoreExpandedBytes}).toString('utf8'))}
  catch{need(false,'INVALID_HANDOVER','The file is not a complete supported gzip handover')}
  need(archive?.schema===SCHEMA&&plain(archive.payload)&&plain(archive.runtime),'UNSUPPORTED_HANDOVER');
  need(archive.payloadSha256===sha(jsonBytes(archive.payload))&&archive.runtimeSha256===sha(jsonBytes(archive.runtime)),
    'HANDOVER_HASH_MISMATCH','The retained handover payload or source manifest changed');
  const p=archive.payload;
  need(plain(p.project)&&Array.isArray(p.records)&&Array.isArray(p.versions)&&Array.isArray(p.files)&&
    plain(p.blobs)&&Array.isArray(p.rows)&&Array.isArray(p.events),'INVALID_HANDOVER_STRUCTURE');
  need(p.records.length<=100000&&p.rows.length<=1000000&&p.files.length<=100000&&p.versions.length<=1000000,
    'HANDOVER_TOO_COMPLEX');
  for(const file of p.files){
    need(typeof file.sha256==='string'&&/^[a-f0-9]{64}$/.test(file.sha256)&&Number.isSafeInteger(file.bytes),'INVALID_SOURCE_MANIFEST');
    const bytes=base64(p.blobs[file.sha256],LIMITS.restoreExpandedBytes);
    need(bytes.length===file.bytes&&sha(bytes)===file.sha256,'ORIGINAL_SOURCE_HASH_MISMATCH');
  }
  need(Array.isArray(archive.runtime.files)&&archive.runtime.files.length<=3000,'INVALID_RUNTIME_MANIFEST');
  for(const file of archive.runtime.files){
    need(typeof file.path==='string'&&!file.path.startsWith('/')&&!file.path.includes('\\')&&
      file.path.split('/').every(part=>part&&part!=='.'&&part!=='..'),'INVALID_RUNTIME_PATH');
    const bytes=base64(file.contentBase64,32*1024*1024);
    need(file.bytes===bytes.length&&file.sha256===sha(bytes),'RUNTIME_SOURCE_HASH_MISMATCH');
  }
  return archive;
}
export function restoreProjectArchive(store,bytes,{name,actor}){
  const archive=readProjectArchive(bytes),p=archive.payload;
  const project=store.newProject(name,{...p.project.config,buyerProfileId:''}),mapping={
    project:{[p.project.id]:project.id},records:{},files:{},rows:{}};
  const kinds=new Set(['requests','collections','captures','jobs','snapshots','comparisons','notes','providerPlans','exports']);
  for(const record of p.records){
    need(kinds.has(record.kind)&&plain(record.value)&&record.value.projectId===p.project.id,'INVALID_RETAINED_RECORD');
    need(!mapping.records[record.value.id],'DUPLICATE_RETAINED_RECORD');mapping.records[record.value.id]=uuid();
  }
  for(const file of p.files){
    need(file.projectId===p.project.id&&!mapping.files[file.id],'INVALID_RETAINED_FILE');
    const created=store.file(project.id,file.name,file.contentType,base64(p.blobs[file.sha256],LIMITS.restoreExpandedBytes));
    store.db.prepare('UPDATE files SET created=? WHERE id=?').run(file.createdAt,created.id);
    mapping.files[file.id]=created.id;
  }
  for(const row of p.rows){
    need(mapping.records[row.ownerId]&&plain(row.value),'INVALID_RETAINED_ROW');
    mapping.rows[row.value.id]??=uuid();
  }
  const rid=value=>value===null||value===undefined?value:mapping.records[value]??value;
  const fid=value=>value===null||value===undefined?value:mapping.files[value]??value;
  const mapRequest=request=>request?{...clone(request),id:rid(request.id),projectId:project.id,
    ...(request.importFileId?{importFileId:fid(request.importFileId)}:{})}:request;
  const mapRow=row=>{
    if(!row)return row;
    const value={...clone(row),id:mapping.rows[row.id]??row.id};
    if(value.sourceCaptureId)value.sourceCaptureId=rid(value.sourceCaptureId);
    if(value.baselineRow)value.baselineRow=mapRow(value.baselineRow);
    if(value.currentRow)value.currentRow=mapRow(value.currentRow);
    return value;
  };
  function mapRecord(kind,input){
    const v={...clone(input),id:rid(input.id),projectId:project.id};
    for(const key of ['requestId','collectionId','parentCaptureId','baselineId','currentId','snapshotId','comparisonId'])if(v[key])v[key]=rid(v[key]);
    for(const key of ['fileId','bodyFileId','headersFileId','challengeFileId','sourceFileId','importFileId'])if(v[key])v[key]=fid(v[key]);
    for(const key of ['requestIds','captureIds'])if(Array.isArray(v[key]))v[key]=v[key].map(rid);
    for(const key of ['sourceFileIds','nativeSourceFileIds'])if(Array.isArray(v[key]))v[key]=v[key].map(fid);
    if(v.request)v.request=mapRequest(v.request);
    if(kind==='notes')v.targetId=v.targetType==='row'?(mapping.rows[v.targetId]??v.targetId):rid(v.targetId);
    if(kind==='jobs'){
      v.items=v.items.map(item=>({...item,requestId:rid(item.requestId),request:mapRequest(item.request),
        ...(item.captureId?{captureId:rid(item.captureId)}:{}),
        ...(item.resultCaptureId?{resultCaptureId:rid(item.resultCaptureId)}:{}),
        nativeSourceFileIds:(item.nativeSourceFileIds??[]).map(fid)}));
      v.originalStatus=v.originalStatus??v.status;v.status='archived';v.restored=true;
      v.restoredFrom={projectId:p.project.id,jobId:input.id,archiveSha256:sha(bytes)};
    }
    if(kind==='exports')v.available=false;
    return v;
  }
  for(const record of p.records){
    const value=mapRecord(record.kind,record.value);
    // Store.put establishes indexes; restore then reinstates the exact retained
    // version and timestamps. No native queue, signer or executor is opened.
    const inserted=store.put(record.kind,value,{history:false});
    store.db.prepare('DELETE FROM versions WHERE id=?').run(inserted.id);
    store.db.prepare('UPDATE records SET version=?,created=?,updated=?,value=? WHERE id=?')
      .run(value.version,value.createdAt,value.updatedAt,JSON.stringify(value),value.id);
  }
  for(const version of p.versions){
    need(kinds.has(version.kind)&&mapping.records[version.value.id],'INVALID_RETAINED_VERSION');
    const value=mapRecord(version.kind,version.value);
    store.db.prepare('INSERT OR IGNORE INTO versions VALUES(?,?,?,?,?,?)')
      .run(value.id,project.id,version.kind,value.version,value.updatedAt??value.createdAt,JSON.stringify(value));
  }
  // Include every current state even when an in-progress job did not write a
  // redundant full version on each progress tick.
  for(const record of p.records){
    const value=mapRecord(record.kind,record.value);
    store.db.prepare('INSERT OR IGNORE INTO versions VALUES(?,?,?,?,?,?)')
      .run(value.id,project.id,record.kind,value.version,value.updatedAt??value.createdAt,JSON.stringify(value));
  }
  const grouped=new Map();
  for(const row of p.rows){
    const owner=rid(row.ownerId);if(!grouped.has(owner))grouped.set(owner,[]);grouped.get(owner).push(mapRow(row.value));
  }
  for(const[owner,rows]of grouped)store.setRows(owner,project.id,rows);
  for(const event of p.events)store.event(project.id,event.actor,event.kind,rid(event.recordId),
    {originalEvent:event,restoredFromProjectId:p.project.id});
  store.event(project.id,actor,'handover.original-restored',project.id,
    {archiveSha256:sha(bytes),originalProjectId:p.project.id,originalPayloadSha256:archive.payloadSha256,
      exactSourceCount:p.files.length,retainedNativeJobsHistorical:true});
  return{project:store.project(project.id),mapping,sourceArchiveSha256:sha(bytes)};
}

// MIT. Local operator HTTP surface over the original retained market model.
import {createServer} from 'node:http';
import {readFile,open,unlink,mkdir} from 'node:fs/promises';
import {join,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {hostname} from 'node:os';
import {MarketModel} from './model.mjs';
import {MarketJobs} from './jobs.mjs';
import {need,jsonBytes,LIMITS,errorView,safeName} from '../common.mjs';

const PUBLIC=fileURLToPath(new URL('./public/',import.meta.url));
const routeKind=value=>value==='provider-plans'?'providerPlans':value;
const DOWNLOAD_NAME=name=>{
  const value=safeName(name),fallback=value.replace(/[^A-Za-z0-9._ -]/g,'_').replace(/["\\]/g,'_');
  return 'attachment; filename="'+fallback+'"; filename*=UTF-8'+String.fromCharCode(39,39)+encodeURIComponent(value);
};
export async function acquireWorkspaceLease(directory){
  await mkdir(directory,{recursive:true,mode:0o700});
  const path=join(resolve(directory),'operator-runtime.json');
  const value={pid:process.pid,host:hostname(),createdAt:new Date().toISOString()};
  for(let attempt=0;attempt<2;attempt++){
    let handle;
    try{handle=await open(path,'wx',0o600);await handle.writeFile(jsonBytes(value));await handle.sync();await handle.close();
      return async()=>{try{const current=JSON.parse(await readFile(path,'utf8'));if(current.pid===value.pid&&current.createdAt===value.createdAt)await unlink(path)}catch(error){if(error.code!=='ENOENT')throw error}}}
    catch(error){
      await handle?.close().catch(()=>{});
      if(handle)await unlink(path).catch(cleanup=>{if(cleanup.code!=='ENOENT')process.stderr.write('Workspace lease cleanup failed: '+cleanup.code+'\n')});
      if(error.code!=='EEXIST')throw error;
      const current=JSON.parse(await readFile(path,'utf8'));
      let alive=true;try{process.kill(current.pid,0)}catch(check){if(check.code==='ESRCH')alive=false}
      need(current.host===hostname()&&!alive,'WORKSPACE_ALREADY_RUNNING','This workspace already has a running native operator process. Use its current browser or close it before starting another worker.',409);
      await unlink(path);
    }
  }
  need(false,'WORKSPACE_LEASE_FAILED');
}
async function requestBody(req,maximum){
  const parts=[];let bytes=0;
  for await(const part of req){bytes+=part.length;need(bytes<=maximum,'REQUEST_TOO_LARGE','Submitted file exceeds the declared limit',413);parts.push(part)}
  let value;try{value=JSON.parse(Buffer.concat(parts).toString('utf8'))}catch{need(false,'INVALID_JSON','Request body must be JSON')}
  need(value!==null&&typeof value==='object'&&!Array.isArray(value),'INVALID_JSON');return value;
}
export async function startMarketWorkspace({directory,port=0,buyerProfiles=[],fetchImpl,allowLocal=false,providerMode,beforeOpen=null,onListening=null,...options}={}){
  need(typeof directory==='string','STATE_DIRECTORY_REQUIRED');
  const release=await acquireWorkspaceLease(resolve(directory));
  let model,runner,server,closing,managedLaunch=null,stopping=false;
  const pending=new Set();
  async function cleanup(){
    stopping=true;
    const failures=[];
    if(server?.listening)await new Promise(done=>{
      server.close(error=>{if(error)failures.push(error);done()});
      server.closeIdleConnections();
    });
    await Promise.allSettled([...pending]);
    try{await runner?.close()}catch(error){failures.push(error)}
    try{model?.close()}catch(error){failures.push(error)}
    try{await release()}catch(error){failures.push(error)}
    if(failures.length){failures[0].cleanupErrors=failures.slice(1).map(errorView);throw failures[0]}
  }
  try{
    need(beforeOpen===null||typeof beforeOpen==='function','INVALID_STARTUP_CALLBACK');
    need(onListening===null||typeof onListening==='function','INVALID_STARTUP_CALLBACK');
    if(beforeOpen)await beforeOpen();
    model=new MarketModel(directory,{buyerProfiles,allowLocal,providerMode,...options});
    runner=new MarketJobs(model,{fetchImpl,probeTimeoutMs:options.probeTimeoutMs??30000}).start();model.attachRunner(runner);
    server=createServer((req,res)=>{const operation=dispatch(req,res).catch(error=>{
      if(res.headersSent){res.destroy();return}
      const status=Number.isInteger(error.status)?error.status:500;
      send(res,status,{error:error.code??'WORKSPACE_ERROR',message:error.message??'The operation failed',
        ...(error.currentRevision===undefined?{}:{currentRevision:error.currentRevision}),
        ...(error.current===undefined?{}:{current:error.current})});
    });pending.add(operation);operation.finally(()=>pending.delete(operation)).catch(()=>{})});
    server.requestTimeout=120000;server.headersTimeout=10000;
    function send(res,status,value,headers={}){
      const bytes=Buffer.isBuffer(value)?value:jsonBytes(value);
      res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store',
        'x-content-type-options':'nosniff','content-length':String(bytes.length),...headers});
      res.end(bytes);
    }
    function result(res,value,status=200){
      if(value?.ok&&['probe','checkout'].includes(value.value?.kind))value={...value,value:model.jobView(value.value)};
      send(res,status,value);
    }
    function download(res,bytes,name,contentType){
      send(res,200,bytes,{'content-type':contentType,'content-disposition':DOWNLOAD_NAME(name)});
    }
    async function dispatch(req,res){
      need(!stopping,'WORKSPACE_CLOSING','The original workspace is closing. Reopen it from its saved application.',503);
      const address=server.address(),allowed=new Set(['127.0.0.1:'+address.port,'localhost:'+address.port,...(address.port===80?['127.0.0.1','localhost']:[])]);
      need(allowed.has(req.headers.host),'INVALID_HOST','Use this workspace’s loopback address',400);
      const base='http://'+req.headers.host,url=new URL(req.url,base),path=url.pathname,query=Object.fromEntries(url.searchParams);
      const write=['POST','PUT','PATCH','DELETE'].includes(req.method);
      if(write){
        need(req.headers['x-workspace-request']==='1','WORKSPACE_REQUEST_HEADER_REQUIRED','Use the workspace’s normal write interface',403);
        need(req.headers.origin===undefined||req.headers.origin===base,'CROSS_ORIGIN_WRITE','The write must come from this workspace',403);
      }
      if(req.method==='GET'&&['/','/app.mjs','/style.css'].includes(path)){
        const name=path==='/'?'index.html':path.slice(1),type=name.endsWith('.html')?'text/html; charset=utf-8':
          name.endsWith('.css')?'text/css; charset=utf-8':'text/javascript; charset=utf-8';
        return send(res,200,await readFile(join(PUBLIC,name)),{'content-type':type,
          'content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"});
      }
      if(req.method==='GET'&&path==='/favicon.ico'){res.writeHead(204);res.end();return}
      need(path.startsWith('/api/'),'NOT_FOUND','Route not found',404);
      const body=write?await requestBody(req,Math.ceil((path==='/api/restore'?LIMITS.restoreBytes:LIMITS.uploadBytes)*4/3)+1048576):null;
      if(req.method==='GET'&&path==='/api/managed-launch'){
        need(managedLaunch,'NOT_FOUND','This native instance has no managed launch.',404);
        return result(res,managedLaunch);
      }
      if(req.method==='GET'&&path==='/api/state')return result(res,model.state());
      if(req.method==='POST'&&path==='/api/projects')return result(res,model.createProject(body),201);
      if(req.method==='POST'&&path==='/api/restore')return result(res,model.restore(body),201);
      let m;
      if((m=/^\/api\/projects\/([^/]+)$/.exec(path))&&req.method==='GET')return result(res,model.project(m[1]));
      if((m=/^\/api\/projects\/([^/]+)\/([^/]+)$/.exec(path))){
        const[,projectId,kind]=m;
        if(req.method==='GET')return result(res,model.list(projectId,routeKind(kind),query));
        if(req.method==='POST'){
          if(kind==='config')return result(res,model.saveConfig(projectId,body));
          if(kind==='requests')return result(res,model.saveRequest(projectId,body));
          if(kind==='collections')return result(res,model.saveCollection(projectId,body));
          if(kind==='collection-import')return result(res,model.importCollection(projectId,body));
          if(kind==='files')return result(res,model.upload(projectId,body));
          if(kind==='imports')return result(res,model.importResponse(projectId,body));
          if(kind==='samples')return result(res,model.sample(projectId,body));
          if(kind==='probes')return result(res,await model.createProbe(projectId,body),202);
          if(kind==='snapshots')return result(res,model.createSnapshot(projectId,body));
          if(kind==='comparisons')return result(res,model.createComparison(projectId,body));
          if(kind==='notes')return result(res,model.saveNote(projectId,body));
          if(kind==='provider-plans')return result(res,await model.saveProviderPlan(projectId,body));
          if(kind==='exports')return result(res,model.exportProject(projectId,body));
        }
      }
      if((m=/^\/api\/requests\/([^/]+)$/.exec(path))){
        if(req.method==='GET')return result(res,model.request(m[1]));
        if(req.method==='POST')return result(res,model.saveRequest(model.store.get('requests',m[1]).projectId,body,m[1]));
      }
      if((m=/^\/api\/collections\/([^/]+)(?:\/(download|checkout))?$/.exec(path))){
        if(req.method==='GET'&&!m[2])return result(res,model.collection(m[1]));
        if(req.method==='GET'&&m[2]==='download')return download(res,model.collectionBytes(m[1]),model.collection(m[1]).collection.name+'.json','application/json');
        if(req.method==='POST'&&m[2]==='checkout')return result(res,await model.createCheckout(m[1],body),202);
        if(req.method==='POST'&&!m[2])return result(res,model.saveCollection(model.store.get('collections',m[1]).projectId,body,m[1]));
      }
      if((m=/^\/api\/files\/([^/]+)(?:\/(download))?$/.exec(path))&&req.method==='GET'){
        const file=model.store.fileInfo(m[1]);
        return m[2]?download(res,model.store.fileBytes(file.id),file.name,file.contentType):result(res,{file});
      }
      if((m=/^\/api\/captures\/([^/]+)(?:\/rows(?:\/([^/]+))?)?$/.exec(path))&&req.method==='GET'){
        return result(res,m[2]?model.captureRow(m[1],m[2]):path.endsWith('/rows')?model.captureRows(m[1],query):model.capture(m[1]));
      }
      if((m=/^\/api\/jobs\/([^/]+)(?:\/(execute|cancel|resume|recover))?$/.exec(path))){
        if(req.method==='GET'&&!m[2])return result(res,model.job(m[1]));
        if(req.method==='POST'&&m[2])return result(res,await model.controlJob(m[1],m[2],body),202);
      }
      if((m=/^\/api\/snapshots\/([^/]+)(?:\/(rows|download))?$/.exec(path))&&req.method==='GET'){
        if(m[2]==='rows')return result(res,model.snapshotRows(m[1],query));
        if(m[2]==='download')return download(res,jsonBytes(model.snapshotDocument(m[1])),model.snapshot(m[1]).snapshot.name+'.json','application/json');
        return result(res,model.snapshot(m[1]));
      }
      if((m=/^\/api\/comparisons\/([^/]+)(?:\/(rows|download))?$/.exec(path))&&req.method==='GET'){
        if(m[2]==='rows')return result(res,model.comparisonRows(m[1],query));
        if(m[2]==='download')return download(res,jsonBytes(model.comparisonDocument(m[1])),model.comparison(m[1]).comparison.name+'.json','application/json');
        return result(res,model.comparison(m[1]));
      }
      if((m=/^\/api\/notes\/([^/]+)$/.exec(path))){
        if(req.method==='GET')return result(res,model.note(m[1]));
        if(req.method==='POST')return result(res,model.saveNote(model.store.get('notes',m[1]).projectId,body,m[1]));
      }
      if((m=/^\/api\/provider-plans\/([^/]+)(?:\/(download))?$/.exec(path))){
        if(req.method==='GET'&&m[2])return download(res,jsonBytes(model.providerDocument(m[1])),model.providerPlan(m[1]).plan.name+'.json','application/json');
        if(req.method==='GET')return result(res,model.providerPlan(m[1]));
        if(req.method==='POST'&&!m[2])return result(res,await model.saveProviderPlan(model.store.get('providerPlans',m[1]).projectId,body,m[1]));
      }
      if((m=/^\/api\/exports\/([^/]+)\/download$/.exec(path))&&req.method==='GET'){
        const{record,bytes}=model.exportBytes(m[1]);return download(res,bytes,record.name+'.json.gz','application/gzip');
      }
      need(false,'NOT_FOUND','API route not found',404);
    }
    await new Promise((done,fail)=>{server.once('error',fail);server.listen(port,'127.0.0.1',done)});
    const url='http://127.0.0.1:'+server.address().port;
    if(onListening)managedLaunch=await onListening({url,model,runner});
    const close=()=>closing??=cleanup();
    return{url,server,model,runner,close};
  }catch(error){
    await cleanup().catch(cleanupError=>{error.cleanupError=errorView(cleanupError)});
    throw error;
  }
}
